\fill[BGBlue!35] (0,0) rectangle (.5,1);
\fill[BGGold!45] (.5,0) rectangle (.75,1);
\fill[BGGreen!40] (.75,0) rectangle (.875,1);
\fill[BGPurple!35] (.875,0) rectangle (.9375,1);
\draw (.5,0)--(.5,1);\draw (.75,0)--(.75,1);\draw (.875,0)--(.875,1);\draw (.9375,0)--(.9375,1);
\node at (.25,.5){$1/2$};\node at (.625,.5){$1/4$};\node at (.8125,.5){$1/8$};
\end{tikzpicture}
\end{bgvisual}
\begin{bgvisualreading}
The uncovered strip after each step is again half as wide as before. The self-similarity is the geometric ratio in visual form.
\end{bgvisualreading}

\begin{bgconcept}[title={Geometric-series formula}]

For \(|r|<1\),
\[
\sum_{n=0}^{\infty}ar^n=\frac{a}{1-r}.
\]
If \(|r|\ge1\), the series diverges.

\end{bgconcept}

\begin{bgguided}[title={Sum a shifted geometric series}]

Consider
\[
\sum_{n=2}^{\infty}5\left(\frac13\right)^n.
\]
The first included term is \(5/9\), and the ratio is \(1/3\). Therefore
\[
\frac{5/9}{1-1/3}=\frac56.
\]
Using the actual first term avoids an indexing error.

\end{bgguided}

\begin{bgexample}[title={A repeating decimal is a convergent series}]
The decimal \(0.272727\ldots\) equals
\[
\frac{27}{100}+\frac{27}{100^2}+\frac{27}{100^3}+\cdots.
\]
This is geometric with first term \(27/100\) and ratio \(1/100\), so
\[
0.272727\ldots=\frac{27/100}{1-1/100}=\frac3{11}.
\]
\end{bgexample}

\begin{bgmistake}[title={Use the first included term}]
For a series starting at \(n=3\), the first term is obtained by substituting \(3\). A shifted index changes the first term even when the ratio is unchanged.
\end{bgmistake}

\begin{bgcheck}{u4a-geometric_series-01}{expression}{6}[Quick check]

Evaluate \(\sum_{n=0}^{\infty}3(1/2)^n\).

\begin{bghint}

Use \(a/(1-r)\).

\end{bghint}

\begin{bgreveal}

\[\frac{3}{1-1/2}=6.\]

\end{bgreveal}

\end{bgcheck}

