\section{Telescoping Series}

\lessonobjective{use partial fractions or algebraic decomposition to expose cancellation and compute a series sum.}

\begin{bgexposition}[title={Write the partial sum before trusting the cancellation}]

A telescoping series contains terms arranged so that most contributions cancel in a finite partial sum. The cancellation is not visible from the infinite notation alone; it appears after several terms are written with their signs. This is why a correct solution displays \(s_N\) rather than announcing that ``everything cancels.''



After cancellation, a few boundary terms remain. The series converges if those remaining terms approach a finite limit. Partial fractions frequently create telescoping structure, especially for rational terms involving consecutive factors such as \(n(n+1)\) or \((n+a)(n+b)\).

\end{bgexposition}

\begin{bgbridge}[title={Cancellation is a fact about partial sums}]
A telescoping series is not a mysterious new species of infinite sum. It is an ordinary series whose finite partial sums simplify because most terms cancel. The safe procedure is therefore to write several terms of \(s_N\), mark the cancellation, and keep the boundary terms that survive. Only after the finite formula is correct do we let \(N\to\infty\).

Partial fractions often reveal the hidden cancellation. The important question is not merely whether adjacent-looking symbols resemble one another, but whether the shifted indices line up across the entire finite sum. A gap of two or three indices may leave several terms at each boundary rather than just one.
\end{bgbridge}

\begin{bgvisual}{u4a-telescoping-cancellation}{Interior terms cancel; boundary terms survive}{A finite telescoping partial sum is displayed as shifted positive and negative rows. Matching interior terms cancel, leaving only terms at the two ends.}
\begin{tikzpicture}[x=1.25cm,y=.8cm,>=Stealth]
\foreach \i/\lab in {0/{1},1/{1/2},2/{1/3},3/{1/4},4/{1/5}}{\node[draw,rounded corners,minimum width=.9cm] at (\i,1) {$+\lab$};}
\foreach \i/\lab in {2/{1/3},3/{1/4},4/{1/5},5/{1/6},6/{1/7}}{\node[draw,rounded corners,minimum width=.9cm] at (\i,0) {$-\lab$};}
\foreach \i in {2,3,4}{\draw[BGRed,very thick] (\i-.35,1.25)--(\i+.35,-.25);}
\node[align=center] at (3,-1) {the middle cancels; the first two and last two terms remain};
\end{tikzpicture}
\end{bgvisual}

\begin{bgproofidea}[title={The limit enters only after the algebra is finite}]
For every fixed \(N\), cancellation is ordinary finite algebra. Once \(s_N\) has been reduced to its surviving terms, convergence is determined by the limit of that finite formula.
\end{bgproofidea}

\begin{bgconcept}[title={Telescoping workflow}]

Decompose the term, write a finite partial sum, cancel only terms actually present, simplify the boundary expression, and then let \(N\to\infty\).

\end{bgconcept}

\begin{bgguided}[title={A standard telescoping sum}]

Since
\[
\frac1{n(n+1)}=\frac1n-\frac1{n+1},
\]
we have
\[
s_N=\left(1-\frac12\right)+\left(\frac12-\frac13\right)+\cdots+\left(\frac1N-\frac1{N+1}\right)=1-\frac1{N+1}.
\]
Thus the infinite series sums to \(1\).

\end{bgguided}

\begin{bgexample}[title={Telescoping with a two-step shift}]
Evaluate
\[
\sum_{n=1}^{\infty}\frac{1}{n(n+2)}.
\]
First decompose
\[
\frac{1}{n(n+2)}=\frac12\left(\frac1n-\frac1{n+2}\right).
\]
Then
\[
s_N=\frac12\left(1+\frac12-\frac1{N+1}-\frac1{N+2}\right).
\]
The final two fractions vanish as \(N\to\infty\), so
\[
\sum_{n=1}^{\infty}\frac{1}{n(n+2)}=\frac12\left(1+\frac12\right)=\frac34.
\]
Notice that two initial terms survive because the shift is two.
\end{bgexample}

\begin{bgmistake}[title={Never cancel inside an unwritten infinite expression}]
Cancellation must be demonstrated in the finite partial sum. Informally crossing out infinitely many terms can hide boundary terms or invalid rearrangements.
\end{bgmistake}

\begin{bgcheck}{u4a-telescoping_series-01}{expression}{1}[Quick check]

Evaluate \(\sum_{n=1}^{\infty}\frac1{n(n+1)}\).

\begin{bghint}

Use \(1/[n(n+1)]=1/n-1/(n+1)\).

\end{bghint}

\begin{bgreveal}

The partial sum is \(1-1/(N+1)\), which approaches \(1\).

\end{bgreveal}

\end{bgcheck}

