\begin{groupplot}[group style={group size=2 by 1,horizontal sep=1.2cm},width=.43\textwidth,height=.31\textwidth,grid=major]
\nextgroupplot[title={terms $1/n$},xlabel={$n$},ymin=0,ymax=1.05]
\addplot[only marks,mark=*,BGBlue] table[row sep=\\]{x y\\1 1\\2 .5\\3 .333\\4 .25\\5 .2\\6 .167\\7 .143\\8 .125\\9 .111\\10 .1\\};
\nextgroupplot[title={partial sums},xlabel={$N$},ymin=0,ymax=3.1]
\addplot[mark=*,BGGold] table[row sep=\\]{x y\\1 1\\2 1.5\\3 1.833\\4 2.083\\5 2.283\\6 2.45\\7 2.593\\8 2.718\\9 2.829\\10 2.929\\};
