\begin{bgproofidea}[title={The theorem is a subtraction of two nearby partial sums}]
If \(s_n\to S\), then also \(s_{n-1}\to S\). Hence
\[
a_n=s_n-s_{n-1}\to S-S=0.
\]
The contrapositive gives the divergence test.
\end{bgproofidea}

\begin{bgconcept}[title={nth-term test}]

If
\[
\lim_{n\to\infty}a_n\ne0
\]
or the limit does not exist, then \(\sum a_n\) diverges. If \(a_n\to0\), the test is inconclusive.

\end{bgconcept}

\begin{bgguided}[title={Divergence hidden by notation}]

For
\[
\sum_{n=1}^{\infty}\frac{n}{n+1},
\]
the terms approach \(1\), not zero. Therefore the series diverges immediately. No comparison or ratio test is needed.

\end{bgguided}

\begin{bgexample}[title={Use the term test before doing anything elaborate}]
Consider
\[
\sum_{n=1}^{\infty}\frac{3n^2+1}{2n^2-5}.
\]
The terms satisfy
\[
\lim_{n\to\infty}\frac{3n^2+1}{2n^2-5}=\frac32\ne0.
\]
Therefore the series diverges immediately. No comparison, ratio test, or partial-fraction work is needed.
\end{bgexample}

\begin{bgmistake}[title={Terms approaching zero do not prove convergence}]
The statement \(a_n\to0\) is necessary, not sufficient. The harmonic series has terms approaching zero and still diverges.
\end{bgmistake}

\begin{bgcheck}{u4a-nth_term_divergence_test-01}{multiple_choice}{diverges}[Quick check]

Does \(\sum_{n=1}^{\infty}\frac{n}{n+1}\) converge or diverge?

\begin{bghint}

First examine the limit of the term.

\end{bghint}

\begin{bgreveal}

Because \(n/(n+1)\to1\ne0\), the series diverges.

\end{bgreveal}

\end{bgcheck}

