\end{bgvisual}

\begin{bgproofidea}[title={The rectangle inequalities differ only at the boundary}]
\begin{bgdecision}[title={Integral Test workflow}]
Write \(a_n=f(n)\). Verify that \(f\) is positive, continuous, and decreasing for all sufficiently large inputs. Evaluate the improper integral with an explicit limit. Finally, transfer only the convergence conclusion to the series; the series sum is not generally equal to the integral.
\end{bgdecision}
For decreasing \(f\),
\[
\int_1^{N+1} f(x)\,dx\le \sum_{n=1}^{N}f(n)
\le f(1)+\int_1^N f(x)\,dx.
\]
These inequalities force the series and improper integral to converge or diverge together.
\end{bgproofidea}

