\begin{bgconcept}[title={Integral Test}]

If \(f\) is positive, continuous, and decreasing for \(x\ge N\), and \(a_n=f(n)\), then
\[
\sum_{n=N}^{\infty}a_n
\quad\text{and}\quad
\int_N^{\infty}f(x)\,dx
\]
either both converge or both diverge.

\end{bgconcept}

\begin{bgguided}[title={A logarithmic example}]

Consider
\[
\sum_{n=2}^{\infty}\frac1{n(\ln n)^2}.
\]
With \(f(x)=1/[x(\ln x)^2]\), substitute \(u=\ln x\):
\[
\int_2^{\infty}\frac{dx}{x(\ln x)^2}
=\int_{\ln2}^{\infty}u^{-2}\,du
=\frac1{\ln2}.
\]
The integral converges, so the series converges.

\end{bgguided}

\begin{bgexample}[title={A logarithmic correction to the harmonic series}]
Test
\[
\sum_{n=2}^{\infty}\frac{1}{n(\ln n)^2}.
\]
Let \(f(x)=1/[x(\ln x)^2]\), which is positive, continuous, and decreasing for \(x\ge2\). Then
\[
\int_2^\infty \frac{dx}{x(\ln x)^2}
=\left[-\frac1{\ln x}\right]_2^\infty
=\frac1{\ln2}.
\]
The improper integral converges, so the series converges.
\end{bgexample}

\begin{bgmistake}[title={Do not forget to verify the hypotheses}]
Writing an improper integral beside a series is not yet an Integral Test argument. State positivity, continuity, and eventual decrease, then evaluate the integral.
\end{bgmistake}

\begin{bgcheck}{u4a-integral_test-01}{multiple_choice}{converges}[Quick check]

Use the Integral Test to classify \(\sum_{n=1}^{\infty}1/n^2\).

\begin{bghint}

Compare with \(\int_1^{\infty}x^{-2}\,dx\).

\end{bghint}

\begin{bgreveal}

The improper integral equals \(1\), so the series converges.

\end{bgreveal}

\end{bgcheck}

