\draw[->] (0,0)--(10,0);
\draw[BGGreen,very thick] (5,-.3)--(5,.3) node[above] {$S$};
\foreach \x/\lab in {1/{s_1},8.7/{s_2},2.7/{s_3},7.4/{s_4},3.7/{s_5},6.5/{s_6},4.25/{s_7},5.9/{s_8}}{\fill[BGGold] (\x,0) circle (2.5pt) node[above=.15cm,font=\scriptsize] {$\lab$};}
