\begin{bgconcept}[title={Alternating Series Test}]

If \(b_n\ge0\), \(b_{n+1}\le b_n\) eventually, and \(b_n\to0\), then
\[
\sum_{n=1}^{\infty}(-1)^{n-1}b_n
\]
converges.

\end{bgconcept}

\begin{bgguided}[title={The alternating harmonic series}]

For \(b_n=1/n\), the magnitudes decrease to zero. Therefore
\[
1-\frac12+\frac13-\frac14+\cdots
\]
converges, even though \(\sum1/n\) diverges.

\end{bgguided}

\begin{bgexample}[title={Decrease may begin after a few terms}]
Test
\[
\sum_{n=2}^{\infty}(-1)^n\frac{\ln n}{n}.
\]
Let \(b_n=\ln n/n\). We have \(b_n\to0\). For \(x>e\),
\[
\frac{d}{dx}\frac{\ln x}{x}=\frac{1-\ln x}{x^2}<0,
\]
so \(b_n\) is decreasing for all sufficiently large \(n\). Therefore the series converges by the Alternating Series Test.
\end{bgexample}

\begin{bgmistake}[title={Check magnitudes, not signed terms}]
The sequence \((-1)^n b_n\) is usually not decreasing. The theorem requires the positive magnitudes \(b_n\) to decrease eventually.
\end{bgmistake}

\begin{bgcheck}{u4a-alternating_series_test-01}{multiple_choice}{converges}[Quick check]

Does \(\sum_{n=1}^{\infty}(-1)^{n-1}/n\) converge?

\begin{bghint}

Check decreasing magnitudes and the limit of \(1/n\).

\end{bghint}

\begin{bgreveal}

Yes. The magnitudes decrease to zero, so the Alternating Series Test applies.

\end{bgreveal}

\end{bgcheck}

